export const Unowned: {
  <T extends object>(attrs: T): T;
  is: (value: unknown) => boolean;
} = Object.assign(
  <T extends object>(attrs: T): T => {
    const cloned = { ...attrs } as T;
    Object.defineProperty(cloned, UnownedTag, {
      value: true,
      enumerable: false,
      writable: false,
      configurable: false,
    });
    return cloned;
  },
  {
    is: (value: unknown): boolean =>
      typeof value === "object" &&
      value !== null &&
      (value as any)[UnownedTag] === true,
  },
);
